package com.pridesys.ticketing.attachment.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.UUID;
@Service public class LocalFileStorage implements FileStorage { private final Path root; public LocalFileStorage(@Value("${app.storage.root:./data/uploads}") String root){this.root=Paths.get(root).toAbsolutePath().normalize();try{Files.createDirectories(this.root);}catch(IOException e){throw new IllegalStateException(e);}} public String store(MultipartFile f)throws IOException{String key=UUID.randomUUID().toString();f.transferTo(root.resolve(key));return key;} public InputStream load(String key)throws IOException{return Files.newInputStream(root.resolve(key).normalize());} public void delete(String key)throws IOException{Files.deleteIfExists(root.resolve(key).normalize());} }
